selector_to_html = {"a[href=\"#sqlite3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. SQLite3<a class=\"headerlink\" href=\"#sqlite3\" title=\"Link to this heading\">#</a></h2><p>\u9ed8\u8ba4\u7684\u6570\u636e\u5e93\u540e\u7aef\u662f <em>SQLite3</em>\uff0c\u4e00\u79cd\u5d4c\u5165\u5f0f\u6570\u636e\u5e93\u3002\n\u5728\u8fd0\u884c\u6027\u80fd\u57fa\u51c6\u6d4b\u8bd5\u4e4b\u524d\uff0c\u8bf7\u786e\u4fdd <code class=\"docutils literal notranslate\"><span class=\"pre\">sqlite3</span></code> \u5e93\u5df2\u7ecf\u88ab\u5b89\u88c5\u3002\n\u5982\u679c\u4f60\u5e0c\u671b\u5c06\u6570\u636e\u5e93\u6587\u4ef6\u4fdd\u5b58\u5728\u4e00\u4e2a\u7279\u5b9a\u4f4d\u7f6e\uff0c\u53ef\u4ee5\u6309\u5982\u4e0b\u65b9\u5f0f\u8bbe\u7f6e\u73af\u5883\u53d8\u91cf\uff1a</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6027\u80fd\u6570\u636e\u5e93\u540e\u7aef<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p><em>FlagGems</em> \u5b9e\u73b0\u4e86\u4e00\u4e2a <code class=\"docutils literal notranslate\"><span class=\"pre\">LibCache</span></code> \u7c7b\uff0c\u7528\u6765\u5c06\u6027\u80fd\u57fa\u51c6\u6d4b\u8bd5\u6570\u636e\u5199\u5165\u6570\u636e\u5e93\u4e2d\u957f\u671f\u4fdd\u5b58\u3002\n<code class=\"docutils literal notranslate\"><span class=\"pre\">LibCache</span></code> \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">sqlalchemy</span></code> \uff08\u4e00\u4e2a\u901a\u7528\u7684\u6570\u636e\u5e93\u62bd\u8c61\u5e93\uff09\u6765\u4e0e\u5177\u4f53\u7684\u6570\u636e\u5e93\u540e\u7aef\u4ea4\u4e92\u3002</p><p>\u4e0e\u540e\u7aef\u6570\u636e\u5e93\u7684\u8fde\u63a5\u4fe1\u606f\u53ef\u4ee5\u4f7f\u7528\u73af\u5883\u53d8\u91cf <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_DB_URL</span></code> \u6765\u8bbe\u7f6e\u3002\n\u672c\u6587\u6863\u4ee5 <em>SQLite3</em> \u548c <em>PostgreSQL</em> \u4e3a\u4f8b\u8bb2\u89e3\u6570\u636e\u5e93\u540e\u7aef\u7684\u914d\u7f6e\uff0c\n\u5982\u679c\u9700\u8981\uff0c\u4f60\u4e5f\u53ef\u4ee5\u4f7f\u7528\u5176\u4ed6\u6570\u636e\u5e93\u7ba1\u7406\u7cfb\u7edf\u6765\u8fdb\u884c\u7c7b\u4f3c\u7684\u914d\u7f6e\u3002</p>", "a[href=\"#postgresql\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. PostgreSQL<a class=\"headerlink\" href=\"#postgresql\" title=\"Link to this heading\">#</a></h2><p>\u4f5c\u4e3a\u4e00\u79cd\u5d4c\u5165\u5f0f\u6570\u636e\u5e93\uff0c<em>SQLite3</em> \u4e0d\u652f\u6301\u540c\u4e00\u65f6\u523b\u5b58\u5728\u591a\u4e2a\u5199\u5165\u8005\u7684\u4f7f\u7528\u573a\u666f\u3002\n\u4f46\u662f\uff0c\u540c\u65f6\u6709\u591a\u4e2a\u5199\u8005\u5199\u5165\u6027\u80fd\u6570\u636e\u662f\u4e00\u79cd\u5f88\u5e38\u89c1\u7684\u4f7f\u7528\u60c5\u51b5\u3002\n\u51fa\u4e8e\u8fd9\u4e00\u539f\u56e0\uff0c\u6211\u4eec\u4e5f\u652f\u6301\u7c7b\u4f3c <em>PostgreSQL</em> \u8fd9\u7c7b\u6570\u636e\u5e93\u4f5c\u4e3a\u540e\u7aef\u6570\u636e\u5e93\u3002\n\u4e0e\u5d4c\u5165\u5f0f\u6570\u636e\u5e93\u4e0d\u540c\uff0c<em>PostgreSQL</em> \u5728\u4f7f\u7528\u4e4b\u524d\u9700\u8981\u4e00\u4e9b\u989d\u5916\u7684\u5b89\u88c5\u90e8\u7f72\u64cd\u4f5c\u3002\n\u4f60\u53ef\u4ee5\u53c2\u9605 <a class=\"reference external\" href=\"https://documentation.ubuntu.com/server/how-to/databases/install-postgresql/\">PostgreSQL \u6587\u6863</a>\n\u4e86\u89e3\u5b89\u88c5\u6307\u4ee4\u3002\u9700\u8981\u6ce8\u610f\u7684\u662f\uff0c\u4f60\u5728\u4f7f\u7528 <em>PostgreSQL</em> \u4e4b\u524d\u5fc5\u987b\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">psycopg</span></code> Python \u5305\u3002</p><p>\u6709\u4e86\u7c7b\u4f3c\u4e8e <em>PostgreSQL</em> \u8fd9\u7c7b\u540e\u7aef\u6570\u636e\u5e93\uff0c\u4f60\u5c31\u53ef\u4ee5\u5c06\u5176\u4f5c\u4e3a\u4e00\u79cd\u8fdc\u7a0b\u6570\u636e\u5e93\uff0c\n\u652f\u6301\u591a\u4e2a <em>FlagGems</em> \u5b9e\u4f8b\u540c\u65f6\u4e0e\u5b83\u5efa\u7acb\u8fde\u63a5\uff0c\u5171\u4eab\u57fa\u51c6\u6d4b\u8bd5\u6570\u636e\u7ed3\u679c\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
